create index if not exists outxout_seen_source_url on public.outxout_sync_entities(last_seen_run,('https://outxout.com/'||source_entity_id)); create or replace function public.outxout_release(p_run uuid,p_token uuid) returns void language plpgsql set search_path=public as $$ begin update outxout_sync_runs set lease_until=null,heartbeat_at=now() where id=p_run and lease_token=p_token; if found and exists(select 1 from outxout_sync_runs r where r.id=p_run and r.phase in('collect','process')) and (exists(select 1 from outxout_sync_work where run_id=p_run and status='pending' and retry_at<=now()) or not exists(select 1 from outxout_sync_work where run_id=p_run and status='pending')) then perform outxout_tick(false); end if; end; $$;